        <li><b>34.0 m +</b><strong>Bedrock aquifer</strong><span>Cased and screened for water supply, or grouted for a heat loop.</span></li></ul></div>[/et_pb_code][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built="1" _builder_version="4.27.4" background_color="#eceef0" custom_padding="110px||110px||true|false" module_class="phx phx--light phx-capability" global_colors_info="{}"][et_pb_row column_structure="1_2,1_2" _builder_version="4.27.4" width="100%" max_width="1280px" custom_padding="0px||0px||false|false" module_class="phx-row" global_colors_info="{}"][et_pb_column type="1_2" _builder_version="4.27.4" custom_padding="|||" custom_padding__hover="|||" global_colors_info="{}"][et_pb_code _builder_version="4.27.4" global_colors_info="{}"]<div class="phx-figure"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 675" role="img" aria-label="A tracked rotary drilling rig coring on a prepared site platform">
