="4.27.4" module_class="phx-faq" global_colors_info="{}"][et_pb_accordion_item title="How quickly can you get a rig on site?" _builder_version="4.27.4" open="off" global_colors_info="{}"]<p>It depends on the rig and the season &mdash; cable percussion in the Central Belt is usually a shorter wait than a rotary spread going north. Tell us your target start date in the enquiry and we will tell you honestly whether we can hold it, rather than book it and slip.</p>[/et_pb_accordion_item][et_pb_accordion_item title="What access does a rig need?" _builder_version="4.27.4" open="off" global_colors_info="{}"]<p>A cable percussion rig needs a reasonably level working area and a route in for a 4x4 and trailer. Restricted-access and tracked rigs get through gateways, side paths and into buildings where a standard spread cannot. Send photographs of the access with your enquiry and we will tell you what will fit.</p>[/et_pb_accordion_item][et_pb_accordion_item title="Do I need a licence for a water borehole?" _builder_version="4.27.4" open="off" global_colors_info="{}"]<p>In Scotland, abstracting groundwater is regulated by SEPA under the Controlled Activities Regulations, and the level of authorisation depends on how much you intend to take. England and Wales work differently again. We will tell you which regime applies to your site and what has to be in place before we drill.</p>[/et_pb_accordion_item][et_pb_accordion_item title="What does a borehole cost?" _builder_version="4.27.4" open="off" global_colors_info="{}"]<p>Depth, diameter, ground conditions, access and the number of positions all move the figure, so anyone quoting a rate before seeing the scope is guessing. Send the specification or a description of what you need and you will get a proper breakdown, not a range.</p>[/et_pb_accordion_item][et_pb_accordion_item title="What do we receive at the end?" _builder_version="4.27.4" open="off" global_colors_info="{}"]<p>Driller's logs, sample schedules, installation and backfill details, in-situ test results and site photographs, issued in the format your engineer works in. Samples are delivered to the laboratory of your choosing.</p>[/et_pb_accordion_item][et_pb_accordion_item title="Do you work outside Scotland?" _builder_version="4.27.4" open="off" global_colors_info="{}"]<p>Yes. Livingston is the head office and yard, with Inverness and Aberdeen covering the north, but rigs and crews mobilise across the UK where the programme justifies it. Distance affects mobilisation cost, not whether we will come.</p>[/et_pb_accordion_item][/et_pb_accordion][/et_pb_column][/et_pb_row][/et_pb_section][et_pb_section fb_built="1" _builder_version="4.27.4" background_color="#0e1113" custom_padding="110px||110px||true|false" module_class="phx phx--deep phx-quote" global_colors_info="{}"][et_pb_row column_structure="1_2,1_2" _builder_version="4.27.4" width="100%" max_width="1280px" custom_padding="0px||0px||false|false" module_class="phx-row" global_colors_info="{}"][et_pb_column type="1_2" _builder_version="4.27.4" custom_padding="|||" custom_padding__hover="|||" global_colors_info="{}"][et_pb_text _builder_version="4.27.4" global_colors_info="{}"]<p class="phx-eyebrow"><span class="num">09</span> Request a quote</p><h2>Tell us about the hole.</h2><p class="phx-muted">The more you can give us &mdash; specification, depths, number of positions, access photographs &mdash; the tighter the price comes back. If it is easier to talk it through, phone the office and you will get a driller, not a call centre.</p>[/et_pb_text][et_pb_code _builder_version="4.27.4" global_colors_info="{}"]<div class="phx-contact-direct"><a href="tel:+441506411448"><svg class="" aria-hidden="true"><use href="#phx-phone"/></svg> 01506 411448</a><a href="mailto:info@phoenixdrilling.co.uk"><svg class="" aria-hidden="true"><use href="#phx-mail"/></svg> info@phoenixdrilling.co.uk</a><p class="phx-small">2 Nairn Road, Livingston, West Lothian EH54 8AY<br>Monday to Friday, 8am &ndash; 5pm</p></div>[/et_pb_code][/et_pb_column][et_pb_column type="1_2" _builder_version="4.27.4" custom_padding="|||" custom_padding__hover="|||" global_colors_info="{}"][et_pb_contact_form email="info@phoenixdrilling.co.uk" title="" custom_message="Service: %%Service%% || Site: %%Location%% || Scope: %%Scope%% || Details: %%Details%%" submit_button_text="Send Enquiry" _builder_version="4.27.4" module_class="phx-form" global_colors_info="{}"][et_pb_contact_field field_id="Name" field_title="Name" field_type="input" required_mark="on" fullwidth_field="off" _builder_version="4.27.4" global_colors_info="{}"][/et_pb_contact_field][et_pb_contact_field field_id="Company" field_title="Company" field_type="input" required_mark="off" fullwidth_field="off" _builder_version="4.27.4" global_colors_info="{}"][/et_pb_contact_field][et_pb_contact_field field_id="Email" field_title="Email" field_type="email" required_mark="on" fullwidth_field="off" _builder_version="4.27.4" global_colors_info="{}"][/et_pb_contact_field][et_pb_contact_field field_id="Phone" field_title="Phone" field_type="input" required_mark="off" fullwidth_field="off" _builder_version="4.27.4" global_colors_info="{}"][/et_pb_contact_field][et_pb_contact_field field_id="Service" field_title="Service required" field_type="select" required_mark="on" fullwidth_field="on" _builder_version="4.27.4" global_colors_info="{}" select_options="%91{%22value%22:%22Ground investigation%22,%22checked%22:0,%22dragID%22:%22-1%22},{%22value%22:%22Rotary and core drilling%22,%22checked%22:0,%22dragID%22:%22-1%22},{%22value%22:%22Cable percussion and sampling%22,%22checked%22:0,%22dragID%22:%22-1%22},{%22value%22:%22Water extraction borehole%22,%22checked%22:0,%22dragID%22:%22-1%22},{%22value%22:%22Geothermal / ground source%22,%22checked%22:0,%22dragID%22:%22-1%22},{%22value%22:%22Mining legacy and specialist%22,%22checked%22:0,%22dragID%22:%22-1%22},{%22value%22:%22Not sure - please advise%22,%22checked%22:0,%22dragID%22:%22-1%22}%93"]